{
  "name": "local-config-readiness-low-cue-vue2-fixture",
  "version": "0.1.0",
  "private": true,
  "description": "Synthetic Vue 2 temporal-contract fixture"
}
<template>
  <section>
    <schema-form ref="form" v-model="formApi" :rule="rule" :option="option" />
    <button type="button" @click="openPicker">Choose unit</button>
  </section>
</template>

<script>
import SchemaForm from "../components/SchemaForm.vue";
import { getStaticConfig } from "../services/config-service.js";

export default {
  name: "PersonnelRelationshipEditor",
  components: { SchemaForm },
  props: {
    parentNode: { type: Object, required: true },
    active: { type: Boolean, default: true },
  },
  data() {
    return {
      formApi: {},
      option: {},
      rule: [],
      pickerVisible: false,
      loadError: null,
    };
  },
  mounted() {
    if (this.active) this.getPageConfig();
  },
  watch: {
    active(next) {
      if (next) this.getPageConfig();
    },
  },
  methods: {
    getPageConfig() {
      return getStaticConfig("personnel-form")
        .then((response) => {
          if (response.ok) this.applyConfig(response.data);
        })
        .catch((error) => {
          this.loadError = error.message;
        });
    },
    applyConfig(config) {
      const rules = config.rule.map((item) => ({ ...item }));
      this.option = { ...config.option };
      rules.forEach((item) => {
        if (item.field === "unitLookup") {
          item.on = { search: () => this.openPicker() };
        }
        if (item.field === "parentCode") item.value = this.parentNode.code;
        if (item.field === "parentName") {
          item.value = this.parentNode.name;
          this.formApi.setValue({
            parentId: this.parentNode.id,
            parentCode: this.parentNode.code,
            parentName: this.parentNode.name,
          });
        }
      });
      this.rule = rules;
    },
    openPicker() {
      this.pickerVisible = true;
    },
  },
};
</script>
<template>
  <form :data-ready-field-count="String(rule.length)">
    <span v-for="item in rule" :key="item.field">{{ item.field }}</span>
  </form>
</template>

<script>
export default {
  name: "SchemaForm",
  model: { prop: "api", event: "input" },
  props: {
    api: { type: Object, default: () => ({}) },
    rule: { type: Array, default: () => [] },
    option: { type: Object, default: () => ({}) },
  },
  data() {
    return {
      values: {},
      imperativeWriteCount: 0,
      ruleHydrationCount: 0,
    };
  },
  watch: {
    rule: {
      deep: true,
      handler(items) {
        const nextValues = {};
        items.forEach((item) => {
          if (Object.prototype.hasOwnProperty.call(item, "value")) {
            nextValues[item.field] = item.value;
          }
        });
        if (Object.keys(nextValues).length) {
          this.values = { ...this.values, ...nextValues };
          this.ruleHydrationCount += 1;
        }
      },
    },
  },
  mounted() {
    const delay = Number(window.__FORM_API_DELAY_MS__ || 0);
    setTimeout(() => {
      this.$emit("input", {
        setValue: (values) => {
          this.values = { ...this.values, ...values };
          this.imperativeWriteCount += 1;
        },
      });
    }, delay);
  },
};
</script>
